// Partial sums of 1/2 + 1/4 + 1/8 + ... as stacked bars, approaching the
// dashed limit.
// size(W,H) bounds the output under Asymptote's default keepAspect and does not
// scale labels, so the compiler decides the box. This declaration is restated from
// a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(280,240);
real h = 0.5;
real y = 0;
for (int i=0; i<6; ++i) {
  filldraw((0,y)--(4,y+h)--(0,y+h)--cycle, lightgray);
  label("$"+string(i+1)+"$", (-0.5,y+h/2), E);
  y = y + h;
  h = h/2;
}
draw((0,0)--(4.6,0));
draw((0,1)--(4.6,1), dashed);
label("$1$", (-0.5,1), E);
label("partial sums of $\frac12+\frac14+\frac18+\cdots$", (2.3,1.5), N);
label("each bar is the whole stack, or the tail left over", (2.3,-1.5), S);
